"""Read-only real NVDA queue transport proof using immutable core11."""
import importlib.util
from pathlib import Path
import sys

LANGUAGE_ORIGIN_SOURCE = "\"\"\"Preserve original NVDA locale provenance through the public sequence filter.\"\"\"\nfrom functools import lru_cache\nfrom threading import RLock\nfrom weakref import ref\n\n\n@lru_cache(maxsize=None)\ndef command_type(parameter_base):\n    \"\"\"Create a real host SynthParamCommand; no NVDA import is required here.\"\"\"\n    class LanguageOriginCommand(parameter_base):\n        # Automatic=False must also replay, superseding earlier explicit state.\n        isDefault = False\n\n        def __init__(self, explicit):\n            if type(explicit) is not bool:\n                raise ValueError(\"Language origin must be explicitly boolean\")\n            self.explicit = explicit\n\n        def __repr__(self):\n            return \"LanguageOriginCommand(explicit=%r)\" % self.explicit\n\n        def __eq__(self, other):\n            return type(self) is type(other) and self.explicit == other.explicit\n\n    return LanguageOriginCommand\n\n\ndef annotate(sequence, language_command, origin_command, end_utterance_command=None, *, default_explicit=False):\n    \"\"\"Add only transport metadata, retaining all original objects and order.\"\"\"\n    if not isinstance(sequence, (list, tuple)):\n        return sequence\n    if (not any(isinstance(item, str) and item.strip() for item in sequence)\n            or any(isinstance(item, origin_command) for item in sequence)):\n        return sequence\n    output = []\n    # A validated typed-event context is an explicit keyboard-locale source,\n    # even when NVDA expresses its default locale as LangChangeCommand(None).\n    explicit = bool(default_explicit)\n    established = False\n    for item in sequence:\n        if isinstance(item, language_command):\n            explicit = bool(item.lang) or bool(default_explicit)\n            output.append(origin_command(explicit))\n            established = True\n        elif isinstance(item, str) and item.strip() and not established:\n            output.append(origin_command(explicit))\n            established = True\n        output.append(item)\n        if end_utterance_command is not None and isinstance(item, end_utterance_command):\n            established = False\n    return output\n\n\nclass Subscription:\n    def __init__(self, owner, point, handler, language_command, origin_command,\n                 end_utterance_command=None, default_explicit=None):\n        self.point = point\n        self.closed = False\n        self._lock = RLock()\n        owner_ref = ref(owner)\n\n        def filter_sequence(sequence, **kwargs):\n            current = owner_ref()\n            if (self.closed or current is None or getattr(current, \"_closed\", False)\n                    or handler.getSynth() is not current\n                    or origin_command not in getattr(current, \"supportedCommands\", ())):\n                return sequence\n            typed = bool(default_explicit(current)) if default_explicit is not None else False\n            return annotate(sequence, language_command, origin_command, end_utterance_command,\n                            default_explicit=typed)\n\n        self.callback = filter_sequence\n        point.register(self.callback)\n\n    def close(self):\n        with self._lock:\n            if self.closed:\n                return False\n            self.closed = True\n            self.point.unregister(self.callback)\n            return True\n\n\ndef subscribe(owner, speech_module, handler, language_command, origin_command,\n              end_utterance_command=None, default_explicit=None):\n    point = getattr(speech_module, \"filter_speechSequence\", None)\n    if point is None or not callable(getattr(point, \"register\", None)) or not callable(getattr(point, \"unregister\", None)):\n        raise RuntimeError(\"NVDA speech.filter_speechSequence is required for Dordiai language provenance\")\n    return Subscription(owner, point, handler, language_command, origin_command,\n                        end_utterance_command, default_explicit)\n"
PROBE_FUNCTION = "\ndef language_origin_transport_probe():\n    \"\"\"Inspect actual host queue objects only; never send custom commands to core11.\"\"\"\n    import itertools\n    import speech\n    from speech import manager as actual_manager\n    from speech.commands import (SynthParamCommand, LangChangeCommand, EndUtteranceCommand,\n        CallbackCommand)\n    namespace = {\"__name__\": \"_dordiai_probe_language_origin\"}\n    exec(LANGUAGE_ORIGIN_SOURCE, namespace)\n    Origin = namespace[\"command_type\"](SynthParamCommand)\n    annotate = namespace[\"annotate\"]\n    checks = []\n    def require(name, passed, **details):\n        checks.append({\"name\": name, \"passed\": bool(passed), **details})\n        if not passed:\n            raise AssertionError(\"Actual NVDA locale origin transport: \" + name)\n    def encode(item):\n        if isinstance(item, Origin):\n            return {\"type\": \"LanguageOriginCommand\", \"explicit\": item.explicit,\n                \"real_synth_parameter\": isinstance(item, SynthParamCommand), \"isDefault\": item.isDefault}\n        if isinstance(item, LangChangeCommand):\n            return {\"type\": type(item).__name__, \"lang\": item.lang}\n        return {\"type\": type(item).__name__, \"text\": item} if isinstance(item,str) else {\"type\":type(item).__name__}\n    # Own normalizer: skip __init__, which registers global synth callbacks.\n    proof = object.__new__(actual_manager.SpeechManager)\n    proof._indexCounter = itertools.count(1)\n    proof._reset()\n    require(\"private_manager_has_no_global_callbacks\", proof is not speech._manager)\n    marker_false, marker_true = Origin(False), Origin(True)\n    original = [marker_false, LangChangeCommand(\"uk\"), \"automatic\", CallbackCommand(lambda:None),\n        \"after_callback\", EndUtteranceCommand(), marker_true, LangChangeCommand(\"ru\"), \"authored\",\n        EndUtteranceCommand(), marker_false, LangChangeCommand(\"uk\"), \"automatic_again\"]\n    processed = proof._processSpeechSequence(original)\n    trace = []\n    for part in processed:\n        state = None\n        for item in part:\n            if isinstance(item, Origin): state = item.explicit\n            if isinstance(item,str): trace.append({\"text\":item, \"local_origin\":state})\n    require(\"real_queue_retains_exact_parameter_objects\", all(\n        any(item is marker for part in processed for item in part)\n        for marker in (marker_false, marker_true)))\n    require(\"index_callback_split_uses_host_commands\", len(proof._indexesToCallbacks) == 1)\n    expected = {\"automatic\":False, \"after_callback\":None, \"authored\":True, \"automatic_again\":False}\n    require(\"original_parameter_order_across_splits\", trace == [\n        {\"text\":text, \"local_origin\":flag} for text,flag in expected.items()], trace=trace)\n    # NVDA resumes priority queues with precisely ParamChangeTracker.getChanged.\n    # Verify both states survive that *actual* replay API, including False.\n    tracker = actual_manager.ParamChangeTracker()\n    tracker.update(marker_true)\n    tracker.update(marker_false)\n    replay = tracker.getChanged()\n    require(\"automatic_overrides_explicit_in_real_replay\", len(replay)==1 and replay[0] is marker_false)\n    tracker.update(marker_true)\n    require(\"explicit_retained_in_real_replay\", tracker.getChanged()==[marker_true])\n    # Exercise real index completion + buildNextUtterance, the same replay path\n    # used when a low-priority queue resumes. No callbacks are executed.\n    from speech.priorities import Spri\n    resume = object.__new__(actual_manager.SpeechManager)\n    resume._indexCounter = itertools.count(1)\n    resume._reset()\n    resume._queueSpeechSequence([marker_false, LangChangeCommand(\"uk\"), \"before_index\",\n        CallbackCommand(lambda:None), \"after_index\"], Spri.NORMAL)\n    resume._curPriQueue = resume._priQueues[Spri.NORMAL]\n    callback_index = next(iter(resume._indexesToCallbacks))\n    valid, ended = resume._removeCompletedFromQueue(callback_index)\n    resumed = resume._buildNextUtterance()\n    require(\"actual_index_completion_and_priority_resume_replays_automatic\", valid and not ended\n        and any(item is marker_false for item in resumed) and \"after_index\" in resumed)\n    # Use the actual public extension point class, but own its instance and do\n    # not register a probe callback on the global running speech filter.\n    point = type(speech.filter_speechSequence)()\n    def private_filter(sequence):\n        return annotate(sequence, LangChangeCommand, Origin, EndUtteranceCommand)\n    point.register(private_filter)\n    fresh = [LangChangeCommand(None), \"fresh_default\"]\n    filtered = point.apply(fresh)\n    require(\"actual_filter_class_retains_original_objects\",\n        isinstance(filtered[0], Origin) and filtered[0].explicit is False and\n        filtered[1] is fresh[0] and filtered[2] is fresh[1])\n    queue = object.__new__(actual_manager.SpeechManager)\n    queue._indexCounter = itertools.count(1)\n    queue._reset()\n    from speech.priorities import Spri\n    first = annotate([LangChangeCommand(\"ru\"), \"first_call\"], LangChangeCommand,Origin,EndUtteranceCommand)\n    second = annotate([\"second_call\"],LangChangeCommand,Origin,EndUtteranceCommand)\n    queue._queueSpeechSequence(first,Spri.NORMAL)\n    queue._queueSpeechSequence(second,Spri.NORMAL)\n    entries = queue._priQueues[Spri.NORMAL].pendingSequences\n    require(\"fresh_high_level_call_resets_queued_origin\", any(\n        any(isinstance(item,Origin) and not item.explicit for item in seq)\n        and \"second_call\" in seq for seq in entries))\n    RESULT[\"language_origin_transport\"] = {\n        \"scope\":\"Actual NVDA generic SynthParamCommand/filter/queue preprocessing and replay API; private queue, no synth delivery\",\n        \"product_source_modified\":False, \"global_manager_modified\":False, \"callbacks_run\":False,\n        \"physical_audio_verified\":False, \"checks\":checks,\n        \"processed\":[[encode(item) for item in part] for part in processed]}\n    check(\"language_origin_actual_transport\", \"passed\", checks=len(checks))\n    save()\n\n\ndef start_language_origin_transport_probe():\n    try:\n        language_origin_transport_probe()\n    except Exception as error:\n        check(\"language_origin_actual_transport\", \"failed\", error_type=type(error).__name__, error=str(error))\n    finally:\n        finish()\n"
ANCHOR = (
    '    later(500, start_required_resource_recovery_probe if SETTINGS.get("required_resource_recovery_probe") else\n'
    '          start_actual_typing_probe if SETTINGS.get("typing_probe") else start_phrase)\n')


def install_language_origin_transport_probe(base):
    original=base.PROBE_PLUGIN
    if original.count(ANCHOR)!=1:
        raise ValueError("NVDA transport anchor differs")
    code="\nLANGUAGE_ORIGIN_SOURCE = "+repr(LANGUAGE_ORIGIN_SOURCE)+"\n"+PROBE_FUNCTION
    candidate=original.replace(ANCHOR,"    later(500, start_language_origin_transport_probe)\n",1)+code
    compile(candidate.replace("__PROBE_SETTINGS__",repr({})).replace(
        "__NATIVE_IMPORT_DIAGNOSTIC__",repr("")),"actual-language-origin-transport","exec")
    base.PROBE_PLUGIN=candidate
    return original


def main(argv=None):
    arguments=list(sys.argv[1:] if argv is None else argv)
    if {"--typing-probe","--fatal-recovery-probe","--required-resource-recovery-probe"}.intersection(arguments):
        raise ValueError("Read-only transport proof cannot be combined with other modes")
    spec=importlib.util.spec_from_file_location("_dordiai_origin_transport_base",
        Path(__file__).with_name("windows_nvda_probe.py"))
    base=importlib.util.module_from_spec(spec)
    spec.loader.exec_module(base)
    install_language_origin_transport_probe(base)
    base.SCOPE="actual-owned-NVDA-private-language-origin-transport"
    return base.main(arguments)


if __name__=="__main__":
    raise SystemExit(main())
